script:
(function () {
  'use strict';
  // Mortgage interest tax saving: federal tax is worked out twice for each loan year, with and
  // without the mortgage deductions, and the difference is the saving.
  //   Deductible interest = interest x min(1, debt limit / average balance for the year)
  //     (Pub. 936 average-balance method using the 12 monthly opening balances)
  //   Itemized = deductible interest (+ points in year 1) + mortgage insurance after phase-out
  //     + SALT (capped, cap reduced above $505,000 of income) + charity above 0.5% of AGI + other,
  //     less the 2/37 reduction for income in the 37% bracket.
  //   Deduction used = larger of itemized, or standard + non-itemizer cash charity deduction.
  //   Tax = 2026 ordinary brackets on AGI - deduction (all income treated as ordinary).
  //   State saving = state rate x deductible mortgage interest, points and insurance.
  // Verified (Node, scratch tests, against an independent amortization and bracket calc):
  //   $400,000 at 6.5% for 30 years -> payment $2,528.27, year-1 interest $25,868.36.
  //   MFJ, $150,000 AGI, $6,000 property tax, $7,000 state tax, $3,000 charity ->
  //   itemized $41,118.36 (charity less 0.5% of AGI) vs standard $32,200 + $2,000 non-itemizer
  //   charity = $34,200; tax $13,377.96 vs $14,900.00 -> year-1 saving $1,522.04 (22% x $6,918.36).
  //   $1,000,000 loan: deductible share = 750,000 / average balance; grandfathered loan uses 1,000,000.
  //
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Brackets, standard deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21).
  // Acquisition debt limit $750,000 ($375,000 MFS); $1,000,000 ($500,000) for debt incurred
  //   before Dec. 16, 2017: IRC 163(h)(3)(F), made permanent by P.L. 119-21; IRS Pub. 936.
  // SALT cap $40,400 ($20,200 MFS), reduced by 30% of AGI over $505,000 ($252,500 MFS):
  //   draft 2026 Schedule A line 5e; floor $10,000 ($5,000 MFS): IRC 164(b)(7).
  // Mortgage insurance premiums: deductible again from 2026 (draft 2026 Schedule A line 8d);
  //   phase-out of 10% per $1,000 (or part) of AGI over $100,000 ($500 / $50,000 MFS): IRC 163(h)(4)(E).
  // Charity: 0.5%-of-AGI floor for itemizers; $1,000 ($2,000 MFJ) cash deduction for
  //   non-itemizers: Form 1040-ES (2026) "What's new".
  // Itemized deduction reduction of 2/37 (about 5.4%) above the 37% bracket threshold:
  //   IRC 68 as amended by P.L. 119-21; Form 1040-ES (2026).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var DEBT_LIMIT = { single: 750000, mfj: 750000, hoh: 750000, mfs: 375000 };
  var DEBT_LIMIT_PRE2018 = { single: 1000000, mfj: 1000000, hoh: 1000000, mfs: 500000 };
  var SALT_CAP = { single: 40400, mfj: 40400, hoh: 40400, mfs: 20200 };
  var SALT_PHASE_START = { single: 505000, mfj: 505000, hoh: 505000, mfs: 252500 };
  var SALT_FLOOR = { single: 10000, mfj: 10000, hoh: 10000, mfs: 5000 };
  var SALT_PHASE_RATE = 0.30;
  var PMI_PHASE_START = { single: 100000, mfj: 100000, hoh: 100000, mfs: 50000 };
  var PMI_PHASE_STEP = { single: 1000, mfj: 1000, hoh: 1000, mfs: 500 };
  var CHARITY_FLOOR = 0.005;
  var NONITEMIZER_CHARITY = { single: 1000, mfj: 2000, hoh: 1000, mfs: 1000 };
  var ITEMIZED_LIMIT_RATE = 2 / 37;
  // ---------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function num(id) {
    var el = document.getElementById(id);
    if (!el) return NaN;
    if (el.value === '') return 0;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function bracketTax(taxable, status) {
    var limits = BRACKETS[status], tax = 0, lower = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable > lower) tax += (Math.min(taxable, upper) - lower) * RATES[i];
      lower = upper;
    }
    return tax;
  }

  // Yearly interest and average balance from a monthly amortization.
  function schedule(loan, annualRate, years) {
    var n = years * 12, r = annualRate / 12;
    var payment = r === 0 ? loan / n : loan * r / (1 - Math.pow(1 + r, -n));
    var bal = loan, out = [];
    for (var y = 0; y < years; y++) {
      var interest = 0, sumBal = 0;
      for (var m = 0; m < 12; m++) {
        sumBal += bal;
        var i = bal * r;
        interest += i;
        bal = Math.max(0, bal - (payment - i));
      }
      out.push({ year: y + 1, interest: interest, avgBalance: sumBal / 12 });
    }
    return { payment: payment, years: out };
  }

  // Federal tax and deduction details for one year, given the mortgage-related deductions.
  function federal(p, mortgageDed) {
    var saltCap = Math.max(SALT_FLOOR[p.status], SALT_CAP[p.status] - SALT_PHASE_RATE * Math.max(0, p.agi - SALT_PHASE_START[p.status]));
    var salt = Math.min(p.propTax + p.stateTax, saltCap);
    var charity = Math.max(0, p.charity - CHARITY_FLOOR * Math.max(0, p.agi));
    var itemized = mortgageDed + salt + charity + p.other;
    var top = BRACKETS[p.status][BRACKETS[p.status].length - 1];
    itemized -= ITEMIZED_LIMIT_RATE * Math.min(itemized, Math.max(0, p.agi - top));
    var standard = STANDARD_DEDUCTION[p.status] + Math.min(p.charity, NONITEMIZER_CHARITY[p.status]);
    var itemize = itemized > standard;
    var deduction = itemize ? itemized : standard;
    return { itemized: itemized, standard: standard, itemize: itemize, deduction: deduction,
             tax: bracketTax(Math.max(0, p.agi - deduction), p.status), saltCap: saltCap };
  }

  function analyse(p) {
    var s = schedule(p.loan, p.rate / 100, p.term);
    var limit = (p.grandfathered ? DEBT_LIMIT_PRE2018 : DEBT_LIMIT)[p.status];
    var over = Math.max(0, p.agi - PMI_PHASE_START[p.status]);
    var pmiShare = Math.max(0, 1 - 0.1 * Math.ceil(over / PMI_PHASE_STEP[p.status]));
    var base = federal(p, 0);
    var rows = [], total = 0, totalInterest = 0;
    s.years.forEach(function (y) {
      var share = y.avgBalance > limit ? limit / y.avgBalance : 1;
      var points = y.year === 1 ? p.points : 0;
      var deductible = (y.interest + points) * share;
      var pmi = y.avgBalance > 0 ? p.pmi * pmiShare : 0;
      var withM = federal(p, deductible + pmi);
      var fedSave = Math.max(0, base.tax - withM.tax);
      var stateSave = p.stateRate / 100 * (deductible + pmi);
      total += fedSave + stateSave;
      totalInterest += y.interest;
      rows.push({ year: y.year, interest: y.interest, points: points, deductible: deductible, pmi: pmi, share: share,
                  withM: withM, fedSave: fedSave, stateSave: stateSave, saving: fedSave + stateSave });
    });
    return { payment: s.payment, rows: rows, total: total, totalInterest: totalInterest, base: base,
             limit: limit, pmiShare: pmiShare };
  }

  function fill(rows) {
    var body = document.getElementById('mxSchedule');
    if (!body) return;
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (r) {
      var tr = document.createElement('tr');
      [String(r.year), money.format(r.interest), money.format(r.deductible + r.pmi), money.format(r.withM.itemized),
       r.withM.itemize ? 'Itemized' : 'Standard', money.format(r.saving)].forEach(function (t, i) {
        var td = document.createElement(i === 0 ? 'th' : 'td');
        if (i === 0) td.setAttribute('scope', 'row');
        td.textContent = t;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  function clear() {
    ['mxSaving', 'mxInterest1', 'mxPayment', 'mxDeductible', 'mxItemized', 'mxStandard', 'mxFedState', 'mxAfterRate', 'mxLifetime']
      .forEach(function (id) { set(id, '–'); });
    fill([]);
    var note = document.getElementById('mxNote');
    if (note) note.hidden = true;
  }

  function update() {
    var statusEl = document.getElementById('mxStatus');
    var gf = document.getElementById('mxGrandfathered');
    var p = {
      loan: num('mxLoan'), rate: num('mxRate'), term: num('mxTerm'),
      status: statusEl && BRACKETS[statusEl.value] ? statusEl.value : 'single',
      agi: num('mxIncome'), propTax: num('mxPropTax'), stateTax: num('mxStateIncomeTax'), charity: num('mxCharity'),
      points: num('mxPoints'), pmi: num('mxPmi'), other: num('mxOther'), stateRate: num('mxStateRate'),
      grandfathered: !!(gf && gf.checked)
    };
    var amounts = [p.loan, p.agi, p.propTax, p.stateTax, p.charity, p.points, p.pmi, p.other];
    var msg = '';
    if (!(p.loan > 0) || p.loan > 1e9) msg = 'Enter a mortgage amount greater than zero.';
    else if (isNaN(p.rate) || p.rate < 0 || p.rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(p.term) || p.term < 1 || p.term > 40 || Math.round(p.term) !== p.term) msg = 'Enter a loan term of 1 to 40 whole years.';
    else if (amounts.some(function (v) { return !isFinite(v) || v < 0 || v > 1e10; })) msg = 'Enter income, taxes and other amounts as numbers of zero or more.';
    else if (isNaN(p.stateRate) || p.stateRate < 0 || p.stateRate > 20) msg = 'Use a state tax rate from 0% to 20%.';
    var error = document.getElementById('mxError');
    if (error) { error.hidden = !msg; error.textContent = msg; }
    if (msg) { clear(); return; }

    var r = analyse(p), y1 = r.rows[0];
    set('mxSaving', money.format(y1.saving));
    set('mxInterest1', money.format(y1.interest));
    set('mxPayment', money.format(r.payment));
    set('mxDeductible', money.format(y1.deductible));
    set('mxItemized', money.format(y1.withM.itemized));
    set('mxStandard', money.format(y1.withM.standard));
    set('mxFedState', money.format(y1.fedSave) + ' / ' + money.format(y1.stateSave));
    var cost = y1.interest + y1.points + p.pmi;
    set('mxAfterRate', cost > 0 ? (p.rate * Math.max(0, 1 - y1.saving / cost)).toFixed(2) + '%' : p.rate.toFixed(2) + '%');
    set('mxLifetime', whole.format(r.total) + ' of ' + whole.format(r.totalInterest) + ' interest');
    fill(r.rows);

    var notes = [];
    if (!y1.withM.itemize) notes.push('Your itemized deductions, including the mortgage, are below the ' + whole.format(y1.withM.standard) +
      ' standard deduction, so the mortgage gives you no federal tax saving this year.');
    else if (!r.base.itemize) notes.push('Without the mortgage you would take the standard deduction, so only the ' +
      money.format(y1.withM.itemized - r.base.standard) + ' by which itemizing beats it reduces your tax.');
    if (y1.share < 1) notes.push('Your average balance is above the ' + whole.format(r.limit) + ' debt limit, so only ' +
      (y1.share * 100).toFixed(1) + '% of the interest is deductible in year 1.');
    if (p.pmi > 0 && r.pmiShare < 1) notes.push(r.pmiShare === 0 ? 'Your income is too high to deduct mortgage insurance premiums.' :
      'Only ' + Math.round(r.pmiShare * 100) + '% of your mortgage insurance premiums are deductible at your income.');
    if (p.propTax + p.stateTax > y1.withM.saltCap) notes.push('State and local taxes are capped at ' + whole.format(y1.withM.saltCap) + ' for your income.');
    var note = document.getElementById('mxNote');
    if (note) { note.hidden = notes.length === 0; note.textContent = notes.join(' '); }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('mxForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
